-- Deck CMS: slides for the public pitch decks (/deck, /tenant-deck),
-- edited via /deck/admin and /tenant-deck/admin on the marketing site.
CREATE TABLE IF NOT EXISTS deck_slides (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  deck TEXT NOT NULL CHECK (deck IN ('tenant', 'whitelabel')),
  position INTEGER NOT NULL,
  template TEXT NOT NULL,
  content JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_deck_slides_deck_pos ON deck_slides (deck, position);

-- Service-role only (marketing API routes); no anon/authenticated policies.
ALTER TABLE deck_slides ENABLE ROW LEVEL SECURITY;

-- Seed from the hand-built static decks — only into an empty table.
INSERT INTO deck_slides (deck, position, template, content)
