  ('tenant', 1, 'cover', $j${"mark": {"en": "Balkina AI · For Your Business", "sr": "Balkina AI · Za vaš biznis"}, "title": {"en": "Automate your booking & fill up your calendar", "sr": "Automatizujte zakazivanje i popunite svoj kalendar"}, "lede": {"en": "with Balkina — an AI booking platform where new customers find you, regulars rebook more often, and your schedule takes care of itself.", "sr": "uz Balkinu — AI platformu za zakazivanje na kojoj vas novi klijenti pronalaze, stalni se vraćaju češće, a raspored se vodi sam."}}$j$::jsonb),
