  ('tenant', 3, 'problem', $j${"eyebrow": {"en": "The Problem", "sr": "Problem"}, "title": {"en": "Bookings you never even saw are going to someone else", "sr": "Rezervacije koje niste ni videli odlaze nekom drugom"}, "gaps": [{"heading": {"en": "Hard to discover", "sr": "Teško vas je pronaći"}, "text": {"en": "New customers can't find you — discovery today is word of mouth and whoever shows up first on Google", "sr": "Novi klijenti ne znaju za vas — otkrivanje se danas svodi na preporuke i na to ko prvi iskoči na Google-u"}}, {"heading": {"en": "Slow to book", "sr": "Sporo zakazivanje"}, "text": {"en": "Booking happens over calls, DMs and email back-and-forth — hours to close what should take seconds", "sr": "Rezervacije idu preko poziva, poruka i mejlova — satima se zatvara ono što traje sekunde"}}, {"heading": {"en": "Missed demand", "sr": "Propuštena tražnja"}, "text": {"en": "Calls while your hands are busy and messages at midnight go unanswered — those bookings go elsewhere", "sr": "Pozivi dok su vam ruke zauzete i poruke u ponoć ostaju bez odgovora — te rezervacije odu drugom"}}, {"heading": {"en": "Forgotten regulars", "sr": "Zaboravljeni stalni klijenti"}, "text": {"en": "Your best customers drift — not because they left, but because nobody reminded them they're due", "sr": "Najbolji klijenti se osipaju — ne zato što su otišli, već zato što ih niko nije podsetio da je vreme"}}]}$j$::jsonb),
  ('tenant', 4, 'points-chat', $j${"eyebrow": {"en": "The Solution", "sr": "Rešenje"}, "title": {"en": "Balkina AI receptionist that never sleeps", "sr": "Balkina AI recepcioner koji nikad ne spava"}, "points": [{"strong": {"en": "New customers will easily discover your business:", "sr": "Novi klijenti će lako otkriti vaš biznis:"}, "text": {"en": "find real-time availability and book your services — day or night", "sr": "vide dostupnost u realnom vremenu i zakazuju vaše usluge — danju i noću"}}, {"strong": {"en": "Instant confirmation or your approval:", "sr": "Trenutna potvrda ili vaše odobrenje:"}, "text": {"en": "you decide which bookings need a yes from you", "sr": "vi odlučujete koje rezervacije traže vaš pristanak"}}, {"strong": {"en": "Every booking lands in one calendar:", "sr": "Svaka rezervacija stiže u jedan kalendar:"}, "text": {"en": "with the customer's details and history attached", "sr": "sa podacima i istorijom klijenta"}}], "msgs": [{"who": "guest", "text": {"en": "Any openings for a cut and beard trim tomorrow after 5?", "sr": "Ima li termina za šišanje i bradu sutra posle 17h?"}}, {"who": "bot", "text": {"en": "Marco has 5:30 or 6:15 free tomorrow. Both take 45 minutes — which suits you?", "sr": "Marko sutra ima slobodno u 17:30 ili 18:15. Oba termina traju 45 minuta — koji vam odgovara?"}}, {"who": "guest", "text": {"en": "5:30, please.", "sr": "17:30, molim."}}]}$j$::jsonb),
